package testdb

import "strings"

// columnTypes fills the schema template for one database.
type columnTypes struct {
	id, timestamp, str, text, boolean string
}

var types = map[string]columnTypes{
	"postgres": {
		"BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
		"TIMESTAMPTZ",
		"VARCHAR(255)",
		"TEXT",
		"BOOLEAN",
	},
	"mysql": {
		"BIGINT AUTO_INCREMENT PRIMARY KEY",
		"DATETIME(6)",
		"VARCHAR(255)",
		"TEXT",
		"BOOLEAN",
	},
	"mariadb": {
		"BIGINT AUTO_INCREMENT PRIMARY KEY",
		"DATETIME(6)",
		"VARCHAR(255)",
		"TEXT",
		"BOOLEAN",
	},
	"sqlite": {
		"INTEGER PRIMARY KEY AUTOINCREMENT",
		"TIMESTAMP",
		"VARCHAR(255)",
		"TEXT",
		"BOOLEAN",
	},
	"sqlserver": {
		"BIGINT IDENTITY PRIMARY KEY",
		"DATETIME2",
		"NVARCHAR(255)",
		"NVARCHAR(MAX)",
		"BIT",
	},
}

// schema returns the statements that recreate the fixture tables. It is
// hand-written because it covers databases migrations do not support yet.
func schema(name string) []string {
	c := types[name]
	replacer := strings.NewReplacer(
		"%ID",
		c.id,
		"%TS",
		c.timestamp,
		"%STR",
		c.str,
		"%TEXT",
		c.text,
		"%BOOL",
		c.boolean,
	)

	return []string{
		"DROP TABLE IF EXISTS posts",
		"DROP TABLE IF EXISTS users",
		replacer.Replace(`CREATE TABLE users (
			id %ID,
			created_at %TS NOT NULL,
			updated_at %TS NOT NULL,
			name %STR NOT NULL,
			email %STR NOT NULL UNIQUE,
			age INT NOT NULL,
			bio %TEXT
		)`),
		replacer.Replace(`CREATE TABLE posts (
			id %ID,
			created_at %TS NOT NULL,
			updated_at %TS NOT NULL,
			user_id BIGINT NOT NULL,
			title %STR NOT NULL,
			published %BOOL NOT NULL,
			FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
		)`),
	}
}
